"""Intent tests for risk.summary_stats (RISK-04, TC-07): the whole-period summary."""

from __future__ import annotations

import math

import pytest

from risk import summary_stats
from risk.types import Returns, TickerSummary, VolSeries


def returns_from_json(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(float(v) for v in vs) for t, vs in data["values"].items()},
    )


def vol_from_json(data: dict) -> VolSeries:
    return VolSeries(
        returns=returns_from_json(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={
            t: tuple(None if v is None else float(v) for v in vs)
            for t, vs in data["values"].items()
        },
    )


@pytest.fixture
def tc07(golden) -> tuple[VolSeries, list[dict], float]:
    data, expected = golden("risk", "TC-07")
    return vol_from_json(data["vol"]), expected["summary"], expected["tol"]


@pytest.mark.intent
def test_tc07_one_summary_per_ticker_in_ticker_order(tc07) -> None:
    vol, expected, _ = tc07
    result = summary_stats(vol)
    assert isinstance(result, tuple)
    assert all(isinstance(s, TickerSummary) for s in result)
    assert [s.ticker for s in result] == [row["ticker"] for row in expected]


@pytest.mark.intent
@pytest.mark.parametrize("field", ["ann_return", "ann_vol", "sharpe"])
def test_tc07_annualized_statistics(tc07, field: str) -> None:
    vol, expected, tol = tc07
    by_ticker = {s.ticker: s for s in summary_stats(vol)}
    for row in expected:
        assert getattr(by_ticker[row["ticker"]], field) == pytest.approx(row[field], abs=tol)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(tc07) -> None:
    vol, expected, tol = tc07
    by_ticker = {s.ticker: s for s in summary_stats(vol)}
    flat = by_ticker["Y"]
    assert flat.ann_vol == pytest.approx(0.0, abs=tol)
    assert flat.sharpe == 0.0
    assert math.isfinite(flat.sharpe)


@pytest.mark.intent
def test_tc07_last_rolling_volatility_is_reported(tc07) -> None:
    vol, expected, tol = tc07
    by_ticker = {s.ticker: s for s in summary_stats(vol)}
    for row in expected:
        last = by_ticker[row["ticker"]].last_vol
        assert last is not None
        assert last == pytest.approx(row["last_vol"], abs=tol)


@pytest.mark.intent
def test_periods_per_year_scales_return_linearly_and_vol_by_root(tc07) -> None:
    vol, _, tol = tc07
    base = {s.ticker: s for s in summary_stats(vol)}
    daily = {s.ticker: s for s in summary_stats(vol, periods_per_year=1)}
    x252, x1 = base["X"], daily["X"]
    assert x1.ann_return * 252 == pytest.approx(x252.ann_return, abs=tol)
    assert x1.ann_vol * math.sqrt(252) == pytest.approx(x252.ann_vol, abs=tol)
    assert x1.sharpe * math.sqrt(252) == pytest.approx(x252.sharpe, abs=tol)


@pytest.mark.intent
def test_fewer_than_two_returns_raises(tc07) -> None:
    vol, _, _ = tc07
    r = vol.returns
    one = VolSeries(
        returns=Returns(
            base_date=r.base_date,
            dates=r.dates[:1],
            tickers=r.tickers,
            values={t: vs[:1] for t, vs in r.values.items()},
        ),
        window=vol.window,
        annualized=vol.annualized,
        values={t: vs[:1] for t, vs in vol.values.items()},
    )
    with pytest.raises(ValueError, match=r"(?i)two|2|return"):
        summary_stats(one)

